/*Query 14 – Running Revenue by Month
Business Scenario

Finance wants cumulative revenue.*/

SELECT
    d.year,
    d.month,
    SUM(f.sales_amount) AS monthly_revenue,
    SUM(SUM(f.sales_amount)) OVER (ORDER BY d.year, d.month) AS running_revenue
FROM fact_sales f
JOIN dim_date d ON f.date_id = d.date_id
GROUP BY d.year, d.month
ORDER BY d.year, d.month;


